	/** 
	 * jumpstart the process by instantiating2 Plant
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		plantId = PlantService.getPlantInstance()
		.createPlant( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PlantService.getPlantInstance()
				.createPlant( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.plantSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Plant : " + successValue.getPlantId());
							  if (successValue.getPlantId().equals(plantId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPlantList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Plant test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on plant consumed")
					);
			subscriber.plantSubscribe( plantId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Plant : " + successValue.getPlantId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPlantList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on plant for plantId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Plant. 
	 */
	protected Plant read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Plant" );

		Plant entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Plant with primary key" );
		msg.append( plantId );
		
		PlantFetchOneSummary fetchOneSummary = new PlantFetchOneSummary( plantId );

		try {
			entity = PlantService.getPlantInstance().getPlant( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Plant " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Plant.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Plant." );

		StringBuilder msg = new StringBuilder( "Failed to update a Plant : " );        
		Plant entity = read();
		UpdatePlantCommand command = generateUpdateCommand();
		command.setPlantId(entity.getPlantId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Plant." );

			// for use later on...
			plantId = entity.getPlantId();

			PlantService proxy = PlantService.getPlantInstance();  

			proxy.updatePlant( command ).get();

			LOGGER.info( "-- Successfully saved Plant - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + plantId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Plant.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Plant." );

		Plant entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Plant with id " + plantId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Plant with id " + plantId );

			throw e;
		}

		try{
			PlantService.getPlantInstance().delete( new DeletePlantCommand( entity.getPlantId() ) ).get();
			LOGGER.info( "-- Successfully deleted Plant with id " + plantId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Plant with id " + plantId );

			throw e;
		}
	}

	/**
	 * get all Plants.
	 */
	protected List<Plant> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Plants:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Plant : " );        
		List<Plant> collection  = new ArrayList<>();

		try {
			// call the static get method on the PlantService
			collection = PlantService.getPlantInstance().getAllPlant();
			assertNotNull( collection, "An Empty collection of Plant was incorrectly returned.");
			
			// Now print out the values
			Plant entity = null;            
			Iterator<Plant> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPlantId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

